{ "summary": "总体语义", "beats": [{ "kind": "answer", "meaning": "必须表达的意思", "required": true }], "goal": "目的", "stance": "立场", "tone": "态度", "verbosity": "brief|normal|detailed|extended", "boundaries": ["不能擅自透露的内容"] }

