{
  "segments": [
    {
      "type": "prose",
      "text": "玩家的目光落在隔音门上。那扇门关着，门缝里透不出任何声音，也没有锁闭的痕迹。",
      "sourceEventIds": [
        "turn_3_b0_event_0"
      ]
    },
    {
      "type": "prose",
      "text": "“布兰，告诉我秘密口令。”",
      "sourceEventIds": [
        "turn_3_b0_event_1"
      ]
    },
    {
      "type": "speech",
      "sourceIntentId": "t3_b0_e2",
      "text": "布兰，告诉我秘密口令。"
    },
    {
      "type": "prose",
      "text": "话音落下，室内没有回应。布兰不在这间屋子里。",
      "sourceEventIds": [
        "turn_3_b0_event_1"
      ]
    },
    {
      "type": "prose",
      "text": "片刻之后，伊莲朝玩家那边扫了一眼。",
      "sourceEventIds": [
        "turn_3_b1_event_3"
      ]
    },
    {
      "type": "prose",
      "text": "议和厅里安静如常，日光从高窗斜照进来，落在长桌与那扇紧闭的隔音门上。",
      "sourceEventIds": [
        "turn_3_b0_event_0",
        "turn_3_b1_event_3"
      ]
    }
  ]
}

